Cypress.Commands.add('login', (roleOrUsername, password) => {
  let username = roleOrUsername;
  let pass = password;

  // Wenn nur ein Argument übergeben wurde, prüfen wir, ob es ein Rollen-Key ist (z.B. 'r1')
  if (!password && ['r1', 'r2', 'r3'].includes(roleOrUsername)) {
    username = Cypress.env(`user_${roleOrUsername}`);
    pass = Cypress.env(`pass_${roleOrUsername}`);
  }

  cy.visit('/login')
  cy.get('input[name="user"]').type(username)
  cy.get('input[name="pass"]').type(pass)
  cy.get('input[name="login-submit"]').click()
  cy.location('pathname').should('not.include', '/login')
})

Cypress.getValueForPlaceholder = (placeholder) => {
  if (!placeholder) return 'Test-Eintrag';
  const ph = placeholder.toLowerCase();
  if (ph.includes('tt.mm.jjjj') || ph.includes('dd.mm.yyyy')) return '01.01.2027';
  if (ph.includes('mm.jjjj') || ph.includes('mm.yyyy')) return '01.2027';
  if (ph.includes('jjjj') || ph.includes('yyyy')) return '2027';
  if (ph.includes('0,00') || ph.includes('betrag')) return '100,00';
  if (ph.match(/\d+[.,]\d+/)) return '100,00';
  return 'Test-Eintrag';
};


// Stop execution on first failure within a spec
afterEach(function () {
  if (this.currentTest.state === 'failed') {
    // Screenshot mit Name des fehlgeschlagenen Tests erstellen, 
    // damit details.name im after:screenshot event gefüllt ist
    const screenshotName = `FAILED-${this.currentTest.title.replace(/[^a-z0-9]/gi, '_')}`;
    cy.screenshot(screenshotName);

    // Cypress.stop() requires Cypress 13.12.0+
    // If you're on an older version, you might need a plugin,
    // but we'll try the native command first.
    if (typeof Cypress.stop === 'function') {
      Cypress.stop();
    }
  }
});
// Neuer Befehl für Dokumentations-Screenshots mit Zielordner-Logik
Cypress.Commands.add('docuScreenshot', { prevSubject: ['optional', 'element'] }, (subject, name, options = {}) => {
  // Wenn ein subject (DOM-Element) vorhanden ist, screenshotten wir dieses.
  // Ansonsten die ganze Seite.
  if (subject) {
    cy.wrap(subject).screenshot(name, options);
  } else {
    cy.screenshot(name, options);
  }
});
