const { defineConfig } = require("cypress");

module.exports = defineConfig({
  e2e: {
    baseUrl: 'http://web',
    supportFile: 'cypress/support/e2e.js',
    viewportWidth: 1280,
    viewportHeight: 720,
    screenshotsFolder: 'docs/Screenshots',
    trashAssetsBeforeRuns: true,
    screenshotOnRunFailure: true,
    video: false,
    env: {
      user_r1: 'r1_user',
      pass_r1: 'r1_password',
      user_r2: 'r2_user',
      pass_r2: 'r2_password',
      user_r3: 'r3_user',
      pass_r3: 'r3_password',
    },
    setupNodeEvents(on, config) {
      on('after:screenshot', (details) => {
        const path = require('path');
        const fs = require('fs');

        // Wir versuchen docu_target_dir aus dem Test-Kontext zu bekommen
        // Falls nicht gesetzt, nutzen wir Fallbacks basierend auf dem Dateinamen
        let targetDir = 'General';
        if (details.specName.includes('benutzerverwaltung') || details.specName.includes('01-infrastruktur_setup')) {
          targetDir = 'Administration/bilder/screenshots';
        } else if (details.specName.includes('aenderungsantraege') || details.specName.includes('fachplanung_erstellen')) {
          targetDir = 'Funktionen/bilder/screenshots';
        }

        // Falls es sich um einen automatischen Fehler-Screenshot handelt, ist name oft undefined
        let fileName = details.name;
        if (!fileName) {
          const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
          fileName = `error-${timestamp}`;
          targetDir = path.join(targetDir, 'errors');
        }

        // Der gewünschte Zielpfad absolut im Projekt (innerhalb docs/)
        const newPath = path.resolve('docs', targetDir, `${fileName}.png`);

        // Sicherstellen, dass das Zielverzeichnis existiert
        if (!fs.existsSync(path.dirname(newPath))) {
          fs.mkdirSync(path.dirname(newPath), { recursive: true });
        }

        // Datei verschieben (Promise für Cypress Node Events)
        return new Promise((resolve, reject) => {
          // Wir nutzen copy + unlink anstelle von rename, da rename über Mount-Grenzen hinweg fehlschlagen kann
          fs.copyFile(details.path, newPath, (err) => {
            if (err) return reject(err);
            fs.unlink(details.path, (err) => {
              if (err) return reject(err);
              resolve({ path: newPath });
            });
          });
        });
      });
    },
  },
});
